class TokenBucket {
  double tokens_, rate_; int burst_; std::mutex m_;
  std::chrono::steady_clock::time_point last_ = std::chrono::steady_clock::now();
public:
  bool try_acquire(double cost = 1.0) {
    std::lock_guard<std::mutex> lk(m_);
    auto now = std::chrono::steady_clock::now();
    tokens_ = std::min(tokens_ + rate_ * std::chrono::duration<double>(now - last_).count(), double(burst_));
    last_ = now;
    if (tokens_ < cost) return false;        // caller: 429 / shed
    tokens_ -= cost; return true;
  }
};

